#[test]
fn test_crypt_is_the_identity_and_image_filters_are_declined() {
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_eq(pf_run(pf_f_crypt(), &crate::testport::hex_blob("0102")[..], 0, 2, out, st, 1), 0, "crypt");
    crate::testport::assert_cells_hex(out, "0102", "unchanged");
    crate::testport::assert_eq(pf_run(pf_f_dct(), &crate::testport::hex_blob("ffd8")[..], 0, 2, out, st, 1), pf_image_filter(), "dct declined");
    crate::testport::assert_eq(crate::port::cells_len(out), 2, "out untouched by an image filter");
    crate::testport::assert_eq(pf_run(99, &crate::testport::hex_blob("00")[..], 0, 1, out, st, 1), pf_unsupported(), "unknown");
}
